import React from 'react';
import styles from './NotificationsPage.module.css';

const NotificationsPage = () => {
    const notifications = [1, 2, 3];

    return (
        <div className={styles.notificationsPage}>
            <div className={styles.container}>
                <div className={styles.header}>
                    <h1 className={styles.title}>Уведомления</h1>
                    <img src="/assets/icons/notification.png" alt="Уведомления" className={styles.icon} />
                </div>

                <div className={styles.notificationsList}>
                    {notifications.map(notif => (
                        <div key={notif} className={styles.notificationItem}>
                            <div className={styles.notificationContent}>
                                <p className={styles.notificationText}>Новое уведомление</p>
                                <span className={styles.notificationDate}>15.04.2024 14:30</span>
                            </div>
                            <button className={styles.deleteButton}>
                                <img src="/assets/icons/bin.png" alt="Удалить" className={styles.deleteIcon} />
                            </button>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default NotificationsPage;
